PrologProcedure:
# the opening balance period (WFP Period, Period Type 'Opening')
sObl = '';
nOP = 1;
WHILE( nOP <= DIMSIZ( 'WFP Period' ) );
   IF( ATTRS( 'WFP Period', DIMNM( 'WFP Period', nOP ), 'Period Type' ) @= 'Opening' ); sObl = DIMNM( 'WFP Period', nOP ); ENDIF;
   nOP = nOP + 1;
END;
IF( sObl @= '' ); ProcessQuit; ENDIF;
#Region WFP Seed Assignments — people, who sits in which Position, Position facts by month
# Bootstrap for the Position + person design: a Position is a budgeted slot; a person is an
# Employee; WFP Assignment says who sits in which Position each month (FTE Share);
# WFP Position Map holds the Position's facts by month (cost centre, company, grade,
# location, Position FTE) so a later change is dated and earlier months stay put.
#   - one Employee per filled Position today (E10001 …): Name, Display alias "Name · ID",
#     Home Entity, Employment Type, Status, Start Period
#   - Assignment, per version: Actual from start to the actuals cut-off;
#     Budget / Forecast / Downside from start to that version's leave month
#     (Hiring Plan Attrition Month, else the Position's End Period). Start Reason
#     'Opening' (in post before the plan window) or 'Hire'; End Reason 'Leaver'.
#   - Position Map for every Position, Dec 2025 .. Dec 2027, every version:
#     the Position's facts from its attributes today; Position FTE in the months the Position
#     exists (filled: from its start; open req: from Jan 2026; to-be-hired: from
#     that version's hire month; until its End Period). A leaver VACATES a Position.
# Re-runnable: pClear = 1 clears both cubes first. Employee IDs follow Position order.
cPos = 'WFP Position';
cEmp = 'WFP Employee';
cPer = 'WFP Period';
cAsg = 'WFP Assignment';
cMap = 'WFP Position Map';
cHP  = 'WFP Hiring Plan';
nFrom = 12;
nTo   = 36;
vVers = 'Budget|Forecast|Downside|';

IF( pClear = 1 );
   CubeClearData( cAsg );
   CubeClearData( cMap );
ENDIF;

nCutoff = CellGetN( 'WFP Assumptions', '2026-01', 'Forecast', 'UK Ltd', 'Actuals Cutoff Index' );
IF( DIMIX( cEmp, 'All Employees' ) = 0 );
   DimensionElementInsertDirect( cEmp, '', 'All Employees', 'C' );
ENDIF;

nPosCount = DIMSIZ( cPos );
nPerCount = DIMSIZ( cPer );
nEmpNo = 0;
nI = 1;
WHILE( nI <= nPosCount );
   vPos = DIMNM( cPos, nI );
   IF( DTYPE( cPos, vPos ) @= 'N' );
      vStatus = ATTRS( cPos, vPos, 'Position Status' );
      vName   = ATTRS( cPos, vPos, 'Incumbent Name' );
      vStart  = ATTRS( cPos, vPos, 'Start Period' );
      vEnd    = ATTRS( cPos, vPos, 'End Period' );
      nFTE    = ATTRN( cPos, vPos, 'FTE' );
      nStart  = IF( vStart @= '', nFrom, ATTRN( cPer, vStart, 'Period Index' ) );
      nSeatEnd = IF( vEnd @= '', 999, ATTRN( cPer, vEnd, 'Period Index' ) );

      # ---- the person in this Position today ----
      vEmp = '';
      IF( vStatus @= 'Filled' & vName @<> '' );
         nEmpNo = nEmpNo + 1;
         vEmp = 'E' | NUMBERTOSTRING( 10000 + nEmpNo );
         IF( DIMIX( cEmp, vEmp ) = 0 );
            DimensionElementInsertDirect( cEmp, '', vEmp, 'N' );
         ENDIF;
         IF( ELISANC( cEmp, 'All Employees', vEmp ) = 0 );
            DimensionElementComponentAddDirect( cEmp, 'All Employees', vEmp, 1 );
         ENDIF;
         AttrPutS( vName, cEmp, vEmp, 'Name' );
         AttrPutS( vName | ' · ' | vEmp, cEmp, vEmp, 'Display' );
         AttrPutS( ATTRS( cPos, vPos, 'Home Entity' ), cEmp, vEmp, 'Home Entity' );
         AttrPutS( ATTRS( cPos, vPos, 'Employment Type' ), cEmp, vEmp, 'Employment Type' );
         AttrPutS( IF( vStart @= '', sObl, vStart ), cEmp, vEmp, 'Start Period' );
         AttrPutS( 'Active', cEmp, vEmp, 'Status' );
      ENDIF;

      nP = 1;
      WHILE( nP <= nPerCount );
         vPer = DIMNM( cPer, nP );
         IF( DTYPE( cPer, vPer ) @= 'N' & ( ( LONG( vPer ) = 7 & SUBST( vPer, 5, 1 ) @= '-' ) % vPer @= sObl ) );
            nIdx = ATTRN( cPer, vPer, 'Period Index' );
            IF( nIdx >= nFrom & nIdx <= nTo );
               # ---- Actual: who sat here, up to the cut-off ----
               IF( vEmp @<> '' & nIdx >= nStart & nIdx <= nCutoff & nIdx <= nSeatEnd );
                  CellPutN( nFTE, cAsg, vPer, 'Actual', vPos, vEmp, 'FTE Share' );
                  IF( nIdx = nStart % ( nIdx = nFrom & nStart < nFrom ) );
                     CellPutS( IF( nStart <= nFrom, 'Opening', 'Hire' ), cAsg, vPer, 'Actual', vPos, vEmp, 'Start Reason' );
                  ENDIF;
               ENDIF;
               IF( nIdx <= nCutoff );
                  CellPutS( ATTRS( cPos, vPos, 'Cost Centre' ), cMap, vPer, 'Actual', vPos, 'Cost Centre' );
                  CellPutS( ATTRS( cPos, vPos, 'Home Entity' ), cMap, vPer, 'Actual', vPos, 'Home Entity' );
                  CellPutS( ATTRS( cPos, vPos, 'Grade' ),       cMap, vPer, 'Actual', vPos, 'Grade' );
                  CellPutS( ATTRS( cPos, vPos, 'Location' ),    cMap, vPer, 'Actual', vPos, 'Location' );
                  nOpenFrom = IF( vStatus @= 'Filled', nStart, IF( vStatus @= 'Open Req', 13, 9999 ) );
                  IF( nIdx >= nOpenFrom & nIdx <= nSeatEnd );
                     CellPutN( nFTE, cMap, vPer, 'Actual', vPos, 'Position FTE' );
                  ENDIF;
               ENDIF;

               # ---- each plan version ----
               vVl = vVers;
               WHILE( SCAN( '|', vVl ) > 1 );
                  nS = SCAN( '|', vVl ); vVer = SUBST( vVl, 1, nS - 1 ); vVl = SUBST( vVl, nS + 1, LONG( vVl ) - nS );
                  nLeave = CellGetN( cHP, vVer, vPos, 'Attrition Month' );
                  nHire  = CellGetN( cHP, vVer, vPos, 'Hire Month' );
                  nPersonEnd = IF( nLeave > 0, nLeave - 1, nSeatEnd );
                  IF( vEmp @<> '' & nIdx >= nStart & nIdx <= nPersonEnd );
                     CellPutN( nFTE, cAsg, vPer, vVer, vPos, vEmp, 'FTE Share' );
                     IF( nIdx = nStart % ( nIdx = nFrom & nStart < nFrom ) );
                        CellPutS( IF( nStart <= nFrom, 'Opening', 'Hire' ), cAsg, vPer, vVer, vPos, vEmp, 'Start Reason' );
                     ENDIF;
                     # leaving: a planned leaver, or the Position's own end (a fixed-term contract)
                     IF( nIdx = nPersonEnd & ( nLeave > 0 % nSeatEnd <= nTo ) );
                        CellPutS( 'Leaver', cAsg, vPer, vVer, vPos, vEmp, 'End Reason' );
                     ENDIF;
                  ENDIF;
                  CellPutS( ATTRS( cPos, vPos, 'Cost Centre' ), cMap, vPer, vVer, vPos, 'Cost Centre' );
                  CellPutS( ATTRS( cPos, vPos, 'Home Entity' ), cMap, vPer, vVer, vPos, 'Home Entity' );
                  CellPutS( ATTRS( cPos, vPos, 'Grade' ),       cMap, vPer, vVer, vPos, 'Grade' );
                  CellPutS( ATTRS( cPos, vPos, 'Location' ),    cMap, vPer, vVer, vPos, 'Location' );
                  nOpenFrom = IF( vStatus @= 'Filled', nStart, IF( vStatus @= 'Open Req', 13, IF( nHire > 0, nHire, 9999 ) ) );
                  IF( nIdx >= nOpenFrom & nIdx <= nSeatEnd );
                     CellPutN( nFTE, cMap, vPer, vVer, vPos, 'Position FTE' );
                  ENDIF;
               END;
            ENDIF;
         ENDIF;
         nP = nP + 1;
      END;
   ENDIF;
   nI = nI + 1;
END;
ASCIIOUTPUT( 'WFP_Seed_Assignments_ok.txt', 'People: ' | NUMBERTOSTRING( nEmpNo ) | ' · cut-off index ' | NUMBERTOSTRING( nCutoff ) );
#EndRegion
